async function collectSycmLiveMetrics(context) {
  const FIELD_LABELS = {
    uv: '访客',
    pv: '浏览量',
    cltItmCnt: '商品收藏人数',
    cartByrCnt: '加购人数',
    cartItemCnt: '加购件数',
    payAmt: '支付金额',
    netPaymentAmount: '净支付金额',
    payByrCnt: '支付买家数',
    payRate: '支付转化率',
    payOrdCnt: '支付子订单数',
    payItmCnt: '支付件数',
    payPct: '客单价',
    p4pExpendAmt: '关键词推广花费',
    cubeAmt: '精准人群推广花费',
    adStrategyAmt: '智能场景花费',
    admCostFamtQzt: '全站推广花费',
    tkExpendAmt: '淘宝客佣金',
    rfdSucAmt: '退款金额(完结时间)',
    payShopRfdAmt: '退款金额(支付时间)',
    ordRfdRate: '订单退款率',
    payAmtRfdRate: '金额退款率',
    realPayrealRfdRate: '签售退款率',
  };
  const PERCENT_FIELDS = new Set(['payRate', 'ordRfdRate', 'payAmtRfdRate', 'realPayrealRfdRate']);

  function pad(n) {
    return String(n).padStart(2, '0');
  }

  function formatDate(date) {
    return date.getFullYear() + '-' + pad(date.getMonth() + 1) + '-' + pad(date.getDate());
  }

  function parseDate(text) {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(text || '').trim());
    if (!match) return null;
    const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
    if (formatDate(date) !== match[0]) return null;
    return date;
  }

  function diffDays(start, end) {
    return Math.round((end.getTime() - start.getTime()) / 86400000) + 1;
  }

  function resolveRange() {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    const requestDateType = String(context.requestDateType || '').trim() || 'day';
    const rawRange = String(context.requestDateRange || '').trim();
    if (requestDateType === 'today') {
      return {
        requestDateType,
        apiMode: 'today',
        dateType: 'today',
        dateRange: '',
        effectiveDateRange: formatDate(today) + '|' + formatDate(today),
        effectiveMetricPeriodLabel: '实时',
      };
    }

    const dateRange = rawRange || (formatDate(yesterday) + '|' + formatDate(yesterday));
    const parts = dateRange.split('|');
    if (parts.length !== 2) {
      throw new Error('requestDateRange 必须是 YYYY-MM-DD|YYYY-MM-DD，留空则默认昨天');
    }
    const start = parseDate(parts[0]);
    const end = parseDate(parts[1]);
    if (!start || !end) {
      throw new Error('requestDateRange 日期格式无效，必须是 YYYY-MM-DD|YYYY-MM-DD');
    }
    if (start > end) {
      throw new Error('requestDateRange 开始日期不能晚于结束日期');
    }
    if (end >= today) {
      throw new Error('requestDateRange 不支持今天或未来日期；实时数据请使用 requestDateType=today');
    }
    const earliest = new Date(today);
    earliest.setFullYear(earliest.getFullYear() - 1);
    if (start < earliest) {
      throw new Error('requestDateRange 不能早于最近一年');
    }
    if (diffDays(start, end) > 31) {
      throw new Error('requestDateRange 最大支持 31 天');
    }

    const __len = diffDays(start, end);
    const __prevEnd = new Date(start);
    __prevEnd.setDate(__prevEnd.getDate() - 1);
    const __prevStart = new Date(__prevEnd);
    __prevStart.setDate(__prevStart.getDate() - (__len - 1));
    const __curRange = formatDate(start) + '|' + formatDate(end);
    const __prevRange = formatDate(__prevStart) + '|' + formatDate(__prevEnd);
    return {
      requestDateType,
      apiMode: 'custom',
      dateType: 'compareRange',
      dateRange: __curRange + ',' + __prevRange,
      effectiveDateRange: __curRange,
      effectiveMetricPeriodLabel: rawRange ? '自定义' : '昨天',
    };
  }

  function readCookie(name) {
    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const match = document.cookie.match(new RegExp('(?:^|;\\s*)' + escaped + '=([^;]*)'));
    return match ? decodeURIComponent(match[1]) : '';
  }

  function resolveToken() {
    const urlToken = new URL(location.href).searchParams.get('token') || '';
    const cookieToken = readCookie('_tb_token_') || readCookie('token');
    const token = urlToken || cookieToken;
    if (!token) {
      throw new Error('未找到生意参谋 token，请确认已登录 sycm.taobao.com 后重试');
    }
    return token;
  }

  function appendQuery(url, query) {
    const u = new URL(url, location.origin);
    Object.entries(query).forEach(function(entry) {
      const key = entry[0];
      const value = entry[1];
      if (value !== undefined && value !== null) {
        u.searchParams.set(key, String(value));
      }
    });
    return u.toString();
  }

  async function fetchJson(url, query) {
    const fullUrl = appendQuery(url, Object.assign({}, query, { _: Date.now(), token }));
    const response = await fetch(fullUrl, {
      credentials: 'include',
      headers: {
        accept: 'application/json, text/plain, */*',
        'sycm-referer': '/portal/home.htm',
      },
    });
    const text = await response.text();
    let json = null;
    try {
      json = text ? JSON.parse(text) : null;
    } catch (error) {
      throw new Error('生意参谋接口返回非 JSON: ' + text.slice(0, 120));
    }
    if (!response.ok) {
      throw new Error('生意参谋接口请求失败 HTTP ' + response.status + ': ' + text.slice(0, 120));
    }
    if (json && json.success === false) {
      throw new Error('生意参谋接口返回失败: ' + (json.message || json.msg || json.errorMsg || JSON.stringify(json).slice(0, 120)));
    }
    return { url: fullUrl, body: json };
  }

  function unwrapPayload(json) {
    const root = json && json.content ? json.content : json;
    const candidates = [
      root && root.data && root.data.data,
      root && root.data && root.data.list,
      root && root.data,
      root,
    ];
    for (let i = 0; i < candidates.length; i += 1) {
      if (candidates[i] && typeof candidates[i] === 'object') return candidates[i];
    }
    return {};
  }

  function pickMetric(source, key) {
    if (!source || typeof source !== 'object') return null;
    const buckets = [source, source.today, source.yestday, source.indexes, source.coreIndex, source.overview, source.data];
    for (let i = 0; i < buckets.length; i += 1) {
      const b = buckets[i];
      if (b && typeof b === 'object' && b[key] !== undefined && b[key] !== null) return b[key];
    }
    return null;
  }

  function normalizeValue(raw, key) {
    if (raw === null || raw === undefined) return '';
    const value = typeof raw === 'object'
      ? (raw.value ?? raw.val ?? raw.v ?? raw.num ?? raw.amount ?? '')
      : raw;
    if (value === null || value === undefined || value === '') return '';
    if (PERCENT_FIELDS.has(key)) {
      const numeric = Number(value);
      if (!Number.isNaN(numeric)) return (numeric * 100).toFixed(2).replace(/\.00$/, '') + '%';
    }
    const numeric = Number(value);
    if (!Number.isNaN(numeric)) return Number.isInteger(numeric) ? String(numeric) : numeric.toFixed(2);
    return String(value);
  }

  function normalizeCycle(raw) {
    if (!raw || typeof raw !== 'object') return '';
    const value = raw.cycleCrc ?? raw.cycleRate ?? raw.crc ?? raw.ratio ?? raw.linkRelativeRatio ?? '';
    if (value === null || value === undefined || value === '') return '';
    return String(value);
  }

  const range = resolveRange();
  const token = resolveToken();
  const device = String(context.device || '0');
  const baseQuery = range.apiMode === 'today'
    ? { needCycleCrc: true, dateType: range.dateType, dateRange: range.dateRange }
    : { needCycleCrc: true, dateType: range.dateType, dateRange: range.dateRange, device: device };

  const overviewUrl = range.apiMode === 'today'
    ? 'https://sycm.taobao.com/portal/live/new/index/overview/v3.json'
    : 'https://sycm.taobao.com/portal/long/period/nodistinct/coreIndex/getShopMainIndexes/v3.json';
  const trendUrl = range.apiMode === 'today'
    ? 'https://sycm.taobao.com/portal/live/new/index/trend/v3.json'
    : 'https://sycm.taobao.com/portal/long/period/nodistinct/coreIndex/new/trend/v3.json';

  const overview = await fetchJson(overviewUrl, baseQuery);
  const trend = await fetchJson(trendUrl, Object.assign({}, baseQuery, { needCycleCrc: undefined }));
  const overviewData = unwrapPayload(overview.body);
  const trendData = unwrapPayload(trend.body);
  const rows = Object.keys(FIELD_LABELS).map(function(key) {
    const raw = pickMetric(overviewData, key);
    return {
      field: key,
      metric: FIELD_LABELS[key],
      value: normalizeValue(raw, key),
      cycleCrc: normalizeCycle(raw),
      periodLabel: range.effectiveMetricPeriodLabel,
      dateRange: range.effectiveDateRange,
    };
  });

  return {
    extractedAt: new Date().toISOString(),
    platform: 'sycm-taobao',
    request: {
      requestDateType: range.requestDateType,
      dateType: range.dateType,
      dateRange: range.dateRange,
      device: device,
      apiMode: range.apiMode,
    },
    effectiveMetricPeriodLabel: range.effectiveMetricPeriodLabel,
    effectiveDateRange: range.effectiveDateRange,
    rows,
    raw: {
      overview: overview.body,
      trend: trend.body,
      overviewData,
      trendData,
    },
    requestUrls: {
      overview: overview.url.replace(/token=[^&]+/, 'token=<redacted>'),
      trend: trend.url.replace(/token=[^&]+/, 'token=<redacted>'),
    },
  };
}
